import axios from 'axios';
import { sanitize } from './utils.js';

/**
 * Extrai dados do PDF via sua API
 * @param {string} url - URL do PDF
 * @returns {Promise<Object>} JSON da API
 */
export async function extractPdf(url) {
  try {
    console.log(`🔄 Processando: ${url}`);

    const response = await axios.get(`${API_URL}`, {
      params: { link: url },
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${API_KEY}`,
      },
      timeout: 30_000, // 30 segundos de espera
    });

    const data = response.data;

    // Validação básica
    if (!data || !data.texto || !data.titulo) {
      throw new Error('A API retornou dados inválidos');
    }

    return {
      titulo: sanitize(data.titulo || 'Documento'),
      autor:  sanitize(data.autor  || 'Não informado'),
      texto:  sanitize(data.texto || ''),
      paginas: data.paginas ?? null,
      fonte:  sanitize(data.fonte  || 'Fonte desconhecida'),
    };

  } catch (err) {
    console.error('❌ Erro na extração:', err.message || err.response?.data);
    throw err;
  }
}
```

