import { Client, EmbedBuilder, CommandInteraction, ChatInputStringCommand } from 'discord.js';
import { extractPdf } from './pdfExtractor.js';
import { prettyPrint, formatList } from './utils.js';

const client = new Client({ intents: ['GuildMessages'] });

// Mapa de comandos
const commands = [
  {
    name: 'extrair',
    description: 'Extraia as informações de um PDF fornecido via link',
    usage: '[link-do-pdf]',
  },
  {
    name: 'lista',
    description: 'Lista de seções do documento (se disponível)',
    usage: '[link-do-pdf]',
  },
];

client.on('interactionCreate', async (interaction) => {
  // Coleta comandos globais (funciona em qualquer servidor)
  if (interaction.commandName) {
    await handleCommand(interaction, commands);
    return;
  }

  // Mensagem normal (@mention)
  if (interaction.member?.user.bot) return;

  const msg = interaction.message.content;
  if (!msg.startsWith('/')) return;

  const cmdMatch = msg.slice(1).trim().split(' ');
  const cmdName = cmdMatch[0];
  const args    = cmdMatch.slice(1).join(' ');

  switch (cmdName) {
    case 'extrair':
      await handleExtract(interaction, args);
      break;
    default:
      await interaction.reply({ content: `❌ Comando não encontrado: ${cmdName}`, ephemeral: true });
  }
});

async function handleCommand(interaction, allCommands) {
  const command = allCommands.find(c => c.name === interaction.commandName);
  if (!command) return;

  // Verifica uso correto de argumentos
  if (interaction.options.none) {
    await interaction.reply({
      content: `❌ Use: /extrair <link-do-pdf>\n${getUsage(command)}`,
      ephemeral: true,
    });
    return;
  }

  const arg = interaction.options.getString('link') ?? '';

  try {
    if (interaction.options.has('link')) {
      const url = interaction.options.getString('link');
      const result = await extractPdf(url);
      await interaction.channel.send(buildEmbed(result, 'extrair'));
    } else {
      // Sem link: mostra exemplo
      await interaction.channel.send(buildEmbed(exemplo(), 'extrair'));
    }
  } catch (err) {
    await interaction.channel.send(buildEmbed({ erro: err.message }, 'extrair', false));
  }
}

function getUsage(cmd) {
  return cmd.usage ? `\n📝 ${cmd.usage}` : '';
}

/**
 * Monta embed bonito com título, descrição, cores etc.
 */
function buildEmbed(data, commandName, isError = false) {
  const base = new EmbedBuilder()
    .setTitle(isError ? '⚠️ Erro' : `✅ ${capitalize(commandName)} PDF`)
    .setDescription(isError
      ? `❌ ${data.erro || 'Algo deu errado'}`
      : `📎 Documento: ${data.titulo || 'Sem título'}`)
    .setColor(isError ? '#FF5733' : '#28A745')
    .addFields(
      { name: 'Autor', value: data.autor || '—', inline: false },
      { name: 'Páginas', value: data.paginas ?? '—', inline: true },
      { name: 'Fonte', value: data.fonte || '—', inline: true },
    )
    .setTimestamp(new Date())
