/**
 * Sanitiza texto evitando emojis ruins ou caracteres perigosos
 */
export function sanitize(text) {
  return text.replace(/[-_&*^{}|<>()]+/g, '').trim();
}

/**
 * Cria uma lista formatada markdown
 */
export function formatList(items) {
  return items.map((item, i) => `**${i + 1}.** ${item}`).join('\n');
}

/**
 * Adiciona emoji e formatação bonita
 */
export function prettyPrint(obj, title = '') {
  if (Array.isArray(obj)) {
    const list = obj.map(v => {
      if (typeof v === 'object' && v !== null) return prettyPrint(v, `• ${title}`);
      return v;
    });
    return `📋 **${title || 'Informações'}**\n${list.join('\n')}`;
  }

  if (typeof obj === 'object' && obj !== null) {
    const lines = Object.entries(obj).map(([key, val]) => {
      const cleanKey = sanitize(String(key));
      const cleanVal = typeof val === 'object' ? JSON.stringify(val) : sanitize(String(val));
      return `▪ **${cleanKey}:** ${cleanVal}`;
    });
    return `💡\n${lines.join('\n')}`;
  }

  return `${title ? `📄 ${title}` : ''}\n${sanitize(String(obj))}`;
}
```

