## 🔧 3. Configuração do Axios com Interceptors

### `plugins/axios-instance.ts`

```typescript
import { defineNuxtPlugin } from '#app'
import axios, { type InternalAxiosRequestConfig } from 'axios'

export default defineNuxtPlugin(() => {
  const instance = axios.create({
    baseURL: process.env.API_URL || 'http://localhost:3000',
    headers: { 'Content-Type': 'application/json' },
  })

  // Interceptante de resposta — adiciona token no header se existir
  instance.response.interceptors.response.use(
    (response) => response,
    async (error) => {
      if (!error.response?.status === 401) return error

      // Token expirado ou inválido → reinicia sessão
      const cookie = document.cookie.match(/(?:^|; )jwt=/s*)/?jwt=/[^;]+/g)
      const newToken = cookie ? decodeURIComponent(cookie[0].split('=')[1]) : null

      if (newToken) {
        try {
          const { data } = await instance.post('/auth/login', {
            username: localStorage.getItem('username') || '',
            password: '', // poderia pedir de novo ao usuário
          })
          if (data.access_token) await useAuthStore().setToken(data.access_token)
          return instance.request(error.config as unknown as InternalAxiosRequestConfig)
        } catch {
          await useAuthStore().logout()
          navigateTo('/login')
        }
      }

      return Promise.reject(error)
    },
  )

  // Interceptante de request — remove corpo em POST/PUT/DELETE
  instance.request.interceptors.request.use(
    (config) => {
      if (['POST', 'PUT', 'PATCH', 'DELETE'].includes(config.method)) {
        config.headers.delete('Content-Type') // Axios envia application/x-www-form-urlencoded por padrão
      }
      return config
    },
  )

  return { instance }
})
```

> ⚠️ Ajuste o interceptor de request conforme sua necessidade. Se seus endpoints aceitam `application/json`, remova a limpeza acima.

