## 🎨 5. Composable de Utilitários JWT

### `composables/useJwt.ts`

```typescript
import { useCookie } from '#app'

export function useJwt() {
  const accessToken = useCookie('jwt', {
    maxAge: 60 * 60, // 1 hora
    sameSite: 'lax',
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
  })

  /** Verifica se o token está válido (não expirado) */
  function validateToken(): boolean {
    try {
      const payload = JSON.parse(atob(accessToken.value?.split('.')[1] ?? ''))
      // Na produção real, faça verificação criptográfica via jwt.verify
      // Aqui só checamos campos básicos
      return !!payload.sub && Date.now() < Number(payload.exp * 1000)
    } catch {
      return false
    }
  }

  /** Extrai dados do token */
  function getUserFromToken() {
    if (!accessToken.value) return null
    try {
      const payload = JSON.parse(atob(accessToken.value.split('.')[1] ?? ''))
      return { id: payload.sub, username: payload.username }
    } catch {
      return null
    }
  }

  return {
    accessToken,
    validateToken,
    getUserFromToken,
  }
}
```

> 💡 Para produção real, substitua o parsing manual por `jsonwebtoken.verify()` no servidor e use `jwt.verify` via `unplugin-jwt` ou chame um proxy API que valide.

