## 🔌 9. Plugin Global de Auth (opcional — sincroniza estado)

### `plugins/auth.plugin.ts`

```typescript
import { defineNuxtPlugin } from '#app'
import { useAuthStore } from '~/stores/auth.store'
import { useJwt } from '~/composables/useJwt'

export default defineNuxtPlugin(() => {
  const store = useAuthStore()
  const jwt = useJwt()

  // Ao carregar, verifica cookie/localStorage
  const initSession = async () => {
    const stored = localStorage.getItem('jwt')
    if (stored) {
      try {
        const cookie = useCookie('jwt')
        const token = stored || cookie.value
        if (token) {
          await store.setToken(token)
          // Carrega usuário do backend caso necessário
          try {
            const { data } = await $fetch<{ id: number; username: string }>('/auth/me', {
              headers: { Authorization: `Bearer ${token}` },
            })
            store.setUser(data)
          } catch {
            // Token expirado → limpa tudo
            store.clearToken()
            store.clearUser()
          }
        }
      } catch {
        store.clearToken()
        store.clearUser()
      }
    }
  }

  watch(
    () => jwt.accessToken.value,
    (val) => {
      if (!val) {
        store.clearToken()
      }
    },
  )

  onMounted(initSession)
})
```

