import { ref, onMounted, watchEffect, useRouter } from 'vue'

export function useAuthGuard(required: boolean) {
  const loading = ref(false)
  const error = ref<string | null>(null)
  const ready = ref(false)

  const authStore = useAuthStore()

  watchEffect(() => {
    if (required && !authStore.isAuthenticated()) {
      ready.value = false
      error.value = 'Não autenticado'
    } else {
      ready.value = true
    }
  })

  onMounted(async () => {
    if (required && !authStore.isAuthenticated()) {
      loading.value = true
      try {
        // Tenta refresh do token
        await authStore.login(/* credenciais */, /* senha */)
        // Redireciona após sucesso
        setTimeout(() => {
          loading.value = false
          ready.value = true
          router.push(originalPath)
        }, 500)
      } catch {
        error.value = 'Falha na autenticação'
        loading.value = false
